from pathlib import Path
import csv,json,hashlib,collections,html,re,datetime
R=Path('/Users/makiko/Documents/exam'); B=R/'final/r_5b1357a9c6-revised'; A=B/'audit/20260924_出版验收复核'; C=B/'chapters'
vs={r['id']:r for r in csv.DictReader((A/'结论与含混论证全稿候选.csv').open())}; defects=[]
def add(ids,title,problem,repair,severity='中',kind='结论含混'):
 refs=[vs['V'+str(i).zfill(3)] for i in ids]
 defects.append(dict(id=f'M{len(defects)+1:03}',severity=severity,kind=kind,title=title,refs=refs,problem=problem,repair=repair,status='已确认写作或论证缺口；不等同于已证明历史判断错误'))
add([1,324,363],'“条件可行”在总论中被升级成“已经能够运作”','舰队实付预算、盟国现金与兵额、英国海上安排仍未联合确定；这些会改变可行分支本身，不只是小数精度。第十章先承认缺口，后又把影响统称为精度与时点，轻化了承重缺口。','全书主结论暂定为有历史构件支持的条件方案；选定一套疆域、预算、外交状态后再检验持续运作。附编逐项标明哪项缺口会改变方向、哪项只改变精度。','高','结论强度越界')
add([5,26,308,320,331],'应当自限与实际上更可能自限，叙述时没有始终分开','正文知道克制违背皇帝惯常偏好，后半书却渐把立宪化当成最看好的发展；缺少促使统治者接受约束的利益联盟与阻力比较。合理的政策建议尚未成为有排序的行为预测。','把主动改革、危机迫改、拒绝改革三线排序；交代大臣、军队、债权人、王室各以何种权力推动或阻止转向。作者可以裁量排序，但须标出理由与改判条件。','高','条件替代结果')
add([3,4,306],'1803年的选择，被1807年已经获胜的条件取代','主线起点透明，并非时间写错；但用户问从1803年怎样取胜，最详细答案却以四场大陆胜利已经实现为条件。1803和1808支线只获得短说明，缺少与主线对称的行动—代价比较。','补1803决策关口，明确此后每一关键行动是否沿用史实、为何当时可选择、失败后如何退回有限目标；并说明为何选择1807整固而非1803和平。','高','问题覆盖不足')
add([1,2,274],'“持久主导”缺少统一验收标准','正文清楚区分控制全欧与大陆议价优势；但“持久”“多数重大问题”“主导”未固定到可观察的外交、军事实绩或终点，可能把法国幸存与欧洲霸权混为不同层级成功。','在1815、1830、1848三个观察点统一检查：直辖核心、盟约履约、第三方结盟、王朝继承和海上通行。说明哪一种失败只削弱王朝，哪一种终止法国霸权。','高','核心概念未定')
add([16,268,272],'人口、疆域与收入没有落在同一个主线年度','第八章地图以38.25百万人起步并含帕尔马等，第一章收入是帝国尺度的规划数；文字警告算法不同，却未给出统一的1807主线—后续疆域—税基对照。','将模型地图逐地区映射到主线取得时间；未并合地区的税、债、军费留在盟国账，取消以不相同疆域互证可行性。','高','跨章假设未统一')
add([21,65,67,101,102,336],'陆海优先级已有方向，分期实施账仍未完成','第一章已明确先大陆后海军，亦列四案预算；但没有说明何时从1.65/1.70亿海军预算升到1.95亿及2.20—2.60亿，也没有把1830舰员流量并入陆军退伍与招募。','补可复算的分期预算与兵员账；基准线只采用负担得起的舰队，高投入另列并写出税收增长、裁军或借款的代价。','高','多变量未闭合')
add([281,295,316],'海军、铁路、盟国补偿和信用担保仍在争用未分配的余额','铁路每年5800万—9300万压力测试、共同基金与海外援助已有材料，但没有统一列入第一章年度用途；书中提醒会挤占，不等于已确定挤掉谁。','建立同年度现金支出与或有担保两张表，明确保留、延期、取消的项目；不得把贷款本金当新增税收，也不得把担保当免费。','高','资源约束未闭合')
add([268],'盟军自养、盟约现金与本国改革的负担缺少逐国验算','有限方案借助约25万自养盟军，另一预算又收4000万盟约现金。正文坦承二者未必兼得，但没有给出可兼得的国家组合。','按意大利、那不勒斯、南德、荷兰、波兰逐一列养兵、驻军、现金与改革支出，择定能同时履约的组合。','高','同盟负担未分配')
add([28,100,313],'“武装共存”究竟是和平、停战还是继续海战，仍未定义','终章把不签和约的共存作为底线，海军追赶却依赖开放航运和连续训练。阶段许可贸易与无封锁海上训练不是同一状态。','明确主线是否停止捕获商船、近海封锁和敌产扣押；若海战继续，使用持续海战分支，武装和平的训练红利另设门槛。','高','外交状态含混')
add([63,66,104,336],'“海军接近英国”仍缺少主线尺度','吨位、舰体、训练权重和全球部署已有区分，范围也诚实公开；问题在于0.552—1.012等跨情景结果未选择与总主线相容的一组，因而尚未回答基准世界究竟缩小多少。','先选可负担的基准预算及英方反应，再给舰体、可动员吨位、近海持续部署三个量级；若只适合定性，明确基准为第二强国且高位追平仅属上行分支。','高','有区间无主线落点')
add([69,102],'英国增加舰队是口头反应，没有回到法国追赶结果','承认对手会应对是优点，但固定英舰规模的试算与内生扩军叙事之间没有再计算或明确的定性回调。','列英国不加码、保近海相对优势、保全球任务三种响应，说明各自压低法国追赶幅度多少，至少给排序及财政代价。','高','对手反应未反馈')
add([293,313],'安特卫普既承担商业和解，又承担海军跃升，取舍未落实','将商业置于入侵象征之上是明确主张，但未决定限制哪些舰种、驻舰数量或出海活动，因而英方接受条件与法方海军收益仍可各取最优。','拟定一个有限基地协议的核心条款，再回填造舰、训练、荷兰通航和英国反应；不用“有限安排”四字替代实际让步。','高','同一资产用途冲突')
add([46,303,304],'英国“更穷”比较的是哪一个世界，没有固定','开放和平可能改善英国相对真实战争史的绝对经济表现，同时降低其相对大陆的领先；正文把绝对收入、工业规模与相对地位置于同一方向判断。','明确三个比较基准：真实历史、永久封锁线、开放和平线；分别裁定英国绝对繁荣和相对份额，不把法国相对获益写成英国必然绝对受损。','中','比较基准含混')
add([96],'马耳他与爱奥尼亚只列谈判因素，未给各自归属排序','两处拥有不同主权与条约起点，却合并成“取决于和谈年份”；没有基准安排。','分两行裁定主线主权、驻军和港口使用权；备选写清需要法国或英国额外付出的交换。')
add([98],'新加坡只解释真实1819年不能照搬，未推到替代终局','指出荷兰、公司及当地统治者都重要，仍未回答英国更可能取得何种海峡节点，法国保荷政策如何改变它。','给主线节点竞争的结果排序：新加坡式协约据点、其他海峡据点、延迟设站，并以当地政治和海路需求说明首选。')
add([148,149,337],'西班牙的波旁延续已经明确，1848年的宪制形态仍悬置','“有限改革”与“某种宪政化”按顺位排列，却未说明排序属于1808、1820还是1848；用户追问的最终王朝—宪制组合尚未完整回答。','分别给短期王朝、中期财政代表、1848终局；明确波旁立宪是否最终首选、如否则何种非立宪制度能承受税债压力。')
add([151,167,172],'伊比利亚和南意大利改革仍以“把问题一起处理”收束','多个必要条件列得充分，但实施者、受损者及妥协次序未确定；教会保障、债权、农地和军饷之间可能冲突。','选择最低改革包并说明谁获益谁付账；明确遇教廷或地主反对时优先保军饷、税源还是土地改革，不能把共同满意当默认。','中','政策清单替代执行')
add([173,216,218,221],'巴西在总结表中重新悬置已确定的主线前提','正文已把1807停止入侵、宫廷短期留里斯本列为主线，汇总却再写“取决于宫廷是否迁都”，并列地区分化、同君、王朝分立而不排序。','主线表固定无1807迁都，给截至1848最看好的政治形态；迟迁都另设分支，不用真实与反事实两线并列代替主线判断。','高','分支回避裁决')
add([203,327],'墨西哥“更久保王”没有推进到本书终点','延长王朝连续性是有根据的方向；“殖民地—自治王国—同君国家—独立国家”在1848究竟哪种最可能仍未选定。','给1848首选法律地位和次选，说明财政代表、官职及对美边疆需求如何促成这个结果；不要求虚构精确独立日。')
add([207],'秘鲁“保住核心”没有划清空间与政治边界','利马、库斯科、上秘鲁、基多、智利与拉普拉塔成本不同；选择保核心是建议，但核心到底包括什么以及与马德里的关系未裁定。','定义优先保存区域及放弃争夺区域，给王权/自治关系和财政援助上限；将被舍弃地区写回邻章终局。')
add([208],'拉普拉塔有商业自治判断，却缺少政治结果首选','同君自治王国、联邦与脱离西班牙均被留下，关键差别仅归结为“让步充分”，没有判断王室是否更可能让步及港口与内陆怎样分权。','选择主线地位，并把布宜诺斯艾利斯、内陆、巴拉圭和东方省的利益拆开；其余方案写成条件分支。')
add([209],'委内瑞拉、基多、智利以“取决于社会联盟”结束','章节拥有分区材料，收束句却没有分别选出联盟和政体结果，地区差异变成列名而不是完成推演。','为三地分别给主线统治联盟、与西班牙关系及改判条件；允许同一地区出现两项排序结论，避免以“独立自治保王并存”替代三份答案。')
add([211,213],'英国转向美洲的两个相反效应没有进入最后排序','补段正确说明省兵与减少紧迫感同时发生；但原段“暂停理由减弱”和补段“无自动替代战场”未合成对亲法西班牙的实际英国政策。','按有限贸易开放/排他法国体系分线，明确英国支持商业、自治、独立或直接军事干预的优先次序，再修正各地区保王结论。','中','反向机制未合成')
add([176,212],'法国援助美洲有四层工具，缺少被主线选中的强度','外交优先和大规模平叛不优先很清楚；军官、军械及有限护航的常态承诺仍无人数、支出、基地或续援频率的可说明量级。','基准只承诺可持续交付的层级；用现有远征和补给案例约束一个标明作者估计的援助包，写清英国截断后止损条件。','高','能力判断未落地')
add([226,227],'希腊只给初始法国政策，没有给1848的政治结果','支持奥斯曼完整是法国偏好，自治或独立是结果选项；二者没有完成冲突裁决，标题“危机仍会发生”比后文的条件结论还强。','区分运动产生、危机升级与国家形成，给自治/独立/镇压的排序，说明俄英行动到哪一步会使法国改策。')
add([230,231],'埃及与叙利亚的冲突识别准确，调停结果仍是空位','“最稳选择是调停”只确定外交方式，不确定苏丹与阿里各得何地何权，因而没有关闭共同盟友提出相反领土要求的矛盾。','明确主线中阿里保有的世袭权与是否取得叙利亚，必要时分短期占领与最终承认；写明法国舍弃哪一项要求。')
add([234],'旁遮普到1848的存续判断被继承条件替代','指出法国援助不是征服踏板很清楚，但延缓吞并、保存自主或仍遭英国控制没有排序；“更稳定继承”尚只是愿望。','以现有继承联盟和财政材料判断其最可能终局，法国技术援助能改变什么、改变不了什么分开，别把稳定继承直接送给分支。')
add([248,253,330],'公司财政国家化、限制战争和预防扩张的关系尚未串成阶段','末章倾向英国更重视预防性控制，但印度章仍把扩张变慢/加快并列；没有分出短期削支与中期夺基地的不同方向。','给阶段机制：哪类压力导致削支、哪类威胁触发夺基地，基准采用哪种组合；据此修改1848印度及海岛终局。','中','阶段机制未完成')
add([251,330],'中国被从过度推演中剥离后，留下的全球推演过薄','不由巴黎决定清朝内政是合理限制；但鸦片、茶、白银和英法力量均已进入材料，最后仍没有裁定这些变量对通商冲突及法国角色的净影响。','补有限范围的结论：英中矛盾是否更可能延续、法方介入排序及海军资源约束；不扩写无材料支撑的全部清朝史。')
add([177,254],'印度洋基地使用“力争保留若干”，没有给组合','法兰西岛、波旁岛、爪哇对英方价值、主权与粮食条件不同；“若干基地”把外交取舍留给读者。','逐岛给主线归属、设防权、补给来源；剔除不保留的据点后重做法国巡航和印度援助路线。','高','主线地图空缺')
add([270,272],'有限省化的下一批名单仍停在“这类地区”','提出三年审计与财政/兵员指标是进步，托斯卡纳和贝格却依然只是类型例子；主线保西班牙、保意大利权利后能否取得它们尚无最终选择。','分保有核心、候选整合、仅同盟三张名单；给每一候选最早谈判阶段与权利人补偿，不以技术适合替代政治取得。','高','行省化路径未具体化')
add([265,174,340],'意大利小规模并合、独立王冠与未来合冠没有共用一张权利图','欧仁、约瑟夫及法国皇储的优先分冠方案明确；但托斯卡纳候选并省和“北中进一步整合”涉及同一领土，尚未说明由法国并省还是由意大利王国吸收。','以土地—统治者—继承权表统一第一章税基、第八章扩展、第五章王冠及末章；主线舍弃一种互斥的领土取得方式。','高','跨章政治权利冲突待解')
add([269],'大范围整合的有利角点被展示，但四条件联合可信度没有排序','正文已承认数学可行不等于政治可行；仍需判断保税、保兵、降驻军、保地方接受能否靠同一制度达到，而不是读者看完“须证明”自行决定。','逐条件列历史类比与代价，判断哪项最先失败、能否补救；给该角点“可推荐/进取试验/仅算术反例”的明确等级。','高','反例未完成裁判')
add([316],'共同财政的制度构件被跳接成“退出不起”','共同工程债与不可退出的政治联合之间，还差税收执行、担保分摊、违约及退出规则；现有类比证明可以合作，不直接证明不可逆中央集权。','给最小基金规模、缴款与表决、违约时谁付、退出怎样清算；把财政合作作为首选，中央主权作为需新增条件的分支。','高','机制跳跃')
add([297,320,325,326],'经济成长到立宪化之间缺少竞争政治联盟','有产者可要求可预测制度，也可支持保护关税、强行政和限制参与；正文从产业成长向预算限制皇权推进较快，反向联盟缺少同等处理。','明确何种税债争执把工业家与地方代表联合起来，军官和地主如何站队；比较威权工业化与有限立宪，不把工业化当单向民主化。','中','因果链过简')
add([287,295,304],'工业铁路有走廊与方向，缺少1848可检验的主线落点','正文已拒绝无依据的提前二十年，但尚未用已有煤铁、资本和造价材料确定基准究竟完成哪些连接、哪些产业差距最难缩小。','按煤、铁、机械、运输分别给等级性终局与核心走廊，成本区间留作压力测试；不强求单一虚假GDP数，也不止步于“有利”。')
add([300],'1816危机写了正确政策，没有推演政府是否执行','开放粮路、信用救济和少征军粮是建议；粮价、出口禁令、地方截留与军队优先权会使它们冲突，缺少一次主线制度受压时的实际裁决。','把1816作为制度压力场景：谁有权开放粮贸、谁借款救济、哪地先缺粮；给较真实历史改善/局部仍恶化的分区判断及理由。','中','规范建议替代事件推演')
