 materials.append(dict(id=f'L{len(materials)+1:03}',title=title,source=path,lines=f'{start}–{end}',target=target,evidence='\n'.join(lines[start-1:end]),missing_content=content,evidence_boundary=boundary,narrative_role=role,status='已确认材料未充分入文；不表示其全部原结论应照抄'))
